B.ai1=s(["300 ml de leche entera","1 pl\xe1tano","40 g de copos de avena","20 g de nueces o almendras"],t.s)
B.akL=s(["Pela el pl\xe1tano y troc\xe9alo.","Echa todo en el vaso de la batidora.","Bate 1 minuto, hasta que no queden trozos.","T\xf3malo enseguida o ll\xe9valo en una botella cerrada (aguanta 1 d\xeda en la nevera)."],t.s)
B.aWh=new A.aS("batido","Batido energ\xe9tico",2,"1 raci\xf3n \xb7 ~570 kcal \xb7 20 g prote\xedna",B.ai1,B.akL,"Si por la ma\xf1ana no tienes hambre, empieza el d\xeda con el batido: se bebe mucho m\xe1s f\xe1cil que un plato.",570,20,B.d2,B.d1,!1)
B.alv=s(["2 rebanadas de pan","2 huevos","1 cucharadita de aceite de oliva","Sal","Opcional: jam\xf3n york o queso"],t.s)
B.akN=s(["Tuesta el pan.","Bate los huevos con una pizca de sal.","Calienta una cucharadita de aceite en una sart\xe9n a fuego medio.","Echa los huevos y remueve sin parar con una esp\xe1tula 2-3 minutos, hasta que cuajen pero sigan jugosos.","Pon un chorrito de aceite en las tostadas y los huevos encima."],t.s)
B.aWB=new A.aS("tostadas-huevos","Tostadas con huevos revueltos",8,"1 raci\xf3n",B.alv,B.akN,"Con prisa: bate los huevos en una taza y cali\xe9ntalos en el microondas en tandas de 30 segundos, removiendo entre medias. O usa 2 huevos cocidos el d\xeda de la compra.",370,20,B.cw,B.ca,!1)
B.ap0=s(["50 g de copos de avena","300 ml de leche entera","1 pl\xe1tano","20 g de nueces","1 cucharada de miel"],t.s)
B.aJk=s(["Pon la avena y la leche en un bol.","Calienta 2 minutos en el microondas (o en un cazo, removiendo).","A\xf1ade el pl\xe1tano en rodajas, las nueces troceadas y la miel."],t.s)
B.aWe=new A.aS("avena","Avena con leche, pl\xe1tano, nueces y miel",5,"1 raci\xf3n",B.ap0,B.aJk,"Puedes dejarla preparada la noche antes en la nevera y tomarla fr\xeda.",660,21,B.cw,B.ca,!1)
B.aCR=s(["40 g de copos de avena","2 huevos","1 pl\xe1tano maduro","Unas gotas de aceite","Miel para servir"],t.s)
B.apI=s(["Tritura la avena, los huevos y el pl\xe1tano hasta tener una masa espesa.",u.s,"Echa un cuchar\xf3n de masa por tortita.","Cuando salgan burbujas (1-2 minutos), dale la vuelta y deja 1 minuto m\xe1s.","S\xedrvelas con miel."],t.s)
B.aWG=new A.aS("tortitas-avena","Tortitas de avena",15,"1 raci\xf3n (4-5 tortitas)",B.aCR,B.apI,"Fuego bajo: si est\xe1 muy fuerte se queman por fuera y quedan crudas por dentro.",440,22,B.cw,B.ca,!1)
B.agR=s(["90 g de macarrones","120 g de carne picada de ternera","100 g de tomate frito","1 cucharadita de aceite de oliva","Sal","Opcional: queso rallado"],t.s)
B.alW=s(["Hierve agua con sal y cuece los macarrones el tiempo que diga el paquete (10-12 minutos).","Mientras, dora la carne en una sart\xe9n con un chorrito de aceite y sal, deshaci\xe9ndola con la esp\xe1tula, 5-6 minutos.","A\xf1ade el tomate frito y deja 3 minutos a fuego bajo.",u.F],t.s)
B.aWj=new A.aS("macarrones-carne","Macarrones con carne picada y tomate",20,"1 raci\xf3n",B.agR,B.alW,"Si un d\xeda te animas, ralla medio calabac\xedn dentro de la salsa: no se nota.",720,34,B.a1,B.cv,!1)
B.apm=s(["170 g de pechuga de pollo","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo o piment\xf3n"],t.s)
B.aub=s(["Cuece el arroz en agua con sal 15-18 minutos (o usa el arroz que dejaste cocido el d\xeda de la compra).","Filetea la pechuga fina y saz\xf3nala.","Calienta bien la plancha con unas gotas de aceite y haz el pollo 3-4 minutos por lado, hasta que no quede rosa por dentro.","S\xedrvelo con el arroz y un chorrito de aceite."],t.s)
B.aWX=new A.aS("pollo-arroz","Pechuga de pollo a la plancha con arroz",20,"1 raci\xf3n",B.apm,B.aub,"El arroz cocido aguanta 3-4 d\xedas en t\xe1per en la nevera.",510,45,B.a1,B.dl,!1)
B.akp=s(["1 kg de calabaza pelada","2 patatas","1 quesito por raci\xf3n (opcional)","Aceite de oliva","Sal"],t.s)
B.ajW=s(["Pela la calabaza y las patatas y c\xf3rtalas en dados.","Ponlas en una olla, c\xfabrelas de agua y a\xf1ade sal y un chorrito de aceite.","Cuece 20-25 minutos, hasta que est\xe9n blandas.","Quita parte del agua y tritura con la batidora hasta que quede cremosa.","Al servir, a\xf1ade un quesito y remueve."],t.s)
B.aX_=new A.aS("crema-calabaza","Crema de calabaza",35,"4 raciones",B.akp,B.ajW,"Gu\xe1rdala en t\xe1pers de una raci\xf3n: 4 d\xedas en la nevera o 3 meses en el congelador. Sin tiempo, c\xf3mprala en brick.",170,5,B.a1,B.eo,!1)
B.awB=s(["3 calabacines","1 patata","2-3 quesitos","Aceite de oliva","Sal"],t.s)
B.agj=s(["Lava los calabacines (no hace falta pelarlos) y c\xf3rtalos en trozos. Pela y trocea la patata.","C\xfabrelos de agua en una olla con sal y un chorrito de aceite.","Cuece 15-20 minutos.","Quita parte del agua, a\xf1ade los quesitos y tritura hasta que quede fina."],t.s)
B.aXs=new A.aS("crema-calabacin","Crema de calabac\xedn",25,"3 raciones",B.awB,B.agj,"Los quesitos le quitan el sabor a verdura y le dan cuerpo.",160,6,B.a1,B.eo,!1)
B.agh=s(["80 g de arroz","150 g de pollo en dados","80 g de jud\xedas verdes congeladas","2 cucharadas de tomate frito","300 ml de agua o caldo","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.arf=s(["Dora el pollo en una cazuela con aceite y sal, 5 minutos.","A\xf1ade las jud\xedas y el tomate frito y rehoga 2 minutos.","Echa el arroz y una pizca de piment\xf3n y remueve 1 minuto.","A\xf1ade el agua caliente y cuece 15-18 minutos a fuego medio sin remover.","Deja reposar 5 minutos tapado."],t.s)
B.aWA=new A.aS("arroz-pollo","Arroz con pollo y jud\xedas verdes",30,"1 raci\xf3n",B.agh,B.arf,null,640,39,B.a1,B.cv,!1)
B.anX=s(["1 lomo de salm\xf3n (descongelado la noche antes)","1 patata grande","1 cucharadita de aceite de oliva","Sal","Opcional: lim\xf3n"],t.s)
B.aCK=s(["Precalienta el horno a 200 \xb0C.","Lava la patata, c\xf3rtala en gajos, ponle aceite y sal y horn\xe9ala 25 minutos.","A\xf1ade el salm\xf3n a la bandeja con sal y aceite y hornea 12-15 minutos m\xe1s.","Est\xe1 hecho cuando se separa en l\xe1minas con el tenedor."],t.s)
B.aWC=new A.aS("salmon-patata","Salm\xf3n al horno con patata asada",40,"1 raci\xf3n",B.anX,B.aCK,"Para ir m\xe1s r\xe1pido: pincha la patata y dale 8 minutos de microondas antes de hornearla.",560,36,B.a1,B.fw,!1)
B.avi=s(["90 g de espaguetis","40 g de bacon","1 huevo + 1 yema","20 g de queso rallado","Pimienta","Sal"],t.s)
B.apz=s(["Cuece la pasta en agua con sal.","Dora el bacon en taquitos en una sart\xe9n sin aceite, 4 minutos.","Bate el huevo, la yema y el queso con pimienta.","Escurre la pasta guardando medio vaso del agua de cocerla.","Fuera del fuego, mezcla la pasta con el bacon y a\xf1ade el huevo removiendo r\xe1pido, con un poco del agua, hasta que quede cremoso."],t.s)
B.aWf=new A.aS("carbonara","Espaguetis carbonara",15,"1 raci\xf3n",B.avi,B.apz,"Siempre fuera del fuego: si no, el huevo se cuaja y queda como un revuelto.",640,29,B.a1,B.cv,!1)
B.aj_=s(["3 huevos","1 patata grande","Aceite de oliva","Sal"],t.s)
B.aoN=s(["Pela las patatas y c\xf3rtalas en l\xe1minas finas.","Fr\xedelas en una sart\xe9n con bastante aceite a fuego medio 15 minutos, hasta que est\xe9n tiernas.","Esc\xfarrelas y m\xe9zclalas con los huevos batidos y sal.","En una sart\xe9n peque\xf1a con 1 cucharada de aceite, echa la mezcla y cuaja 3-4 minutos.","Dale la vuelta con ayuda de un plato y deja 2 minutos m\xe1s."],t.s)
B.aXi=new A.aS("tortilla-patata","Tortilla de patata",30,"1 raci\xf3n grande",B.aj_,B.aoN,"M\xe1s r\xe1pido y con menos aceite: haz las patatas 6-7 minutos en el microondas, tapadas, en vez de fre\xedrlas.",600,28,B.a1,B.eo,!1)
B.aic=s(["150 g de lomo de cerdo en filetes","100 ml de salsa de champi\xf1\xf3n de bote","1 patata grande","1 cucharadita de aceite de oliva","Sal"],t.s)
B.agF=s([u.m,"Sazona los filetes y d\xf3ralos a fuego fuerte 2 minutos por lado.","Baja el fuego, a\xf1ade la salsa y deja 3-4 minutos.","S\xedrvelo con las patatas."],t.s)
B.aWH=new A.aS("lomo-champinon","Lomo en salsa de champi\xf1\xf3n con patatas al horno",35,"1 raci\xf3n",B.aic,B.agF,"Se puede hacer por lotes el jueves y guardar 3 d\xedas en la nevera.",560,39,B.a1,B.dl,!1)
B.atg=s(["180 g de merluza (descongelada la noche antes)","80 g de arroz","1 cucharadita de aceite de oliva","Sal","Ajo en polvo","Opcional: lim\xf3n"],t.s)
B.axB=s(["Cuece el arroz o usa el que tengas cocido.","Seca bien la merluza con papel de cocina y saz\xf3nala.","Hazla en la plancha con aceite, primero por el lado de la piel 4 minutos y luego 2-3 minutos por el otro.","S\xedrvela con el arroz y un chorrito de aceite."],t.s)
B.aWu=new A.aS("merluza-arroz","Merluza a la plancha con arroz",20,"1 raci\xf3n",B.atg,B.axB,null,470,36,B.a1,B.fw,!1)
B.amo=s(["90 g de pasta (h\xe9lices o macarrones)","2 latas de at\xfan","3 cucharadas de ma\xedz","8 aceitunas","\xbd pepino (opcional)","2 cucharaditas de aceite de oliva","Sal"],t.s)
B.aA1=s(["Cuece la pasta, esc\xfarrela y enfr\xedala con agua fr\xeda.","M\xe9zclala con el at\xfan escurrido, el ma\xedz, las aceitunas en rodajas y el pepino en dados.","Ali\xf1a con aceite y sal.","Gu\xe1rdala en un t\xe1per en la nevera."],t.s)
B.aWa=new A.aS("ensalada-pasta","Ensalada de pasta con at\xfan, ma\xedz y aceitunas",15,"1 t\xe1per",B.amo,B.aA1,"Aguanta 2 d\xedas en la nevera. Ideal para d\xedas de evento.",730,42,B.a1,B.eU,!1)
B.apM=s(["3 huevos","Sal","1 cucharadita de aceite","Opcional: queso o jam\xf3n"],t.s)
B.any=s(["Bate los huevos con sal.","Calienta el aceite en una sart\xe9n a fuego medio.","Echa los huevos y, cuando cuajen los bordes, dobla la tortilla por la mitad.","Deja 30 segundos m\xe1s y s\xedrvela."],t.s)
B.aWM=new A.aS("tortilla-francesa","Tortilla francesa",5,"1 raci\xf3n",B.apM,B.any,null,300,23,B.a1,B.eo,!1)
B.ayV=s(["1-2 hamburguesas de ternera","1 pan de hamburguesa o 2 rebanadas","1 loncha de queso","Tomate frito o tu salsa","1 patata mediana","1 cucharadita de aceite de oliva","Sal"],t.s)
B.al5=s([u.m,"Haz la hamburguesa en la plancha bien caliente, 3-4 minutos por lado.","Pon el queso encima el \xfaltimo minuto para que se funda.","Monta la hamburguesa en el pan con la salsa."],t.s)
B.aWE=new A.aS("hamburguesa","Hamburguesa casera con queso y patatas al horno",35,"1 raci\xf3n",B.ayV,B.al5,null,750,37,B.a1,B.dl,!1)
B.agO=s(["1-2 tortillas de wrap","120 g de pollo en tiras","1 loncha de queso","2 cucharadas de ma\xedz","\xbc de pepino en tiras","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
B.axg=s(["Saltea el pollo con aceite, sal y piment\xf3n 6-7 minutos.","Calienta la tortilla 20 segundos en una sart\xe9n.","Rell\xe9nala con el pollo, el queso, el ma\xedz y el pepino.","Enr\xf3llala doblando primero los extremos."],t.s)
B.aWW=new A.aS("wrap-pollo","Wrap de pollo con queso, ma\xedz y pepino",15,"1 raci\xf3n",B.agO,B.axg,"Envuelto en papel de aluminio sirve para llevar.",530,35,B.a1,B.eU,!1)
B.ajA=s(["200 g de arroz","200 g de pollo troceado","100 g de lomo o costilla de cerdo","100 g de jud\xedas verdes","2 cucharadas de tomate frito","800 ml de agua o caldo","Aceite, sal, piment\xf3n","Colorante o azafr\xe1n"],t.s)
B.akg=s(["Dora la carne en la paellera con aceite y sal, 8 minutos.","A\xf1ade las jud\xedas y rehoga 3 minutos.","A\xf1ade el tomate y el piment\xf3n y remueve 1 minuto.","Echa el agua caliente y el colorante y deja que hierva.","Reparte el arroz: 10 minutos a fuego fuerte y 8 a fuego suave, sin remover.","Deja reposar 5 minutos tapada con un trapo."],t.s)
B.aXe=new A.aS("paella",u.gs,45,"2 raciones",B.ajA,B.akg,"La segunda raci\xf3n, a un t\xe1per para otro d\xeda o al congelador.",740,37,B.a1,B.cv,!1)
B.akz=s(["90 g de pasta","2 latas de at\xfan","100 g de tomate frito","Opcional: queso rallado"],t.s)
B.am3=s(["Cuece la pasta en agua con sal.","Calienta el tomate con el at\xfan escurrido 2 minutos.",u.F],t.s)
B.aWx=new A.aS("pasta-atun","Pasta con tomate y at\xfan",15,"1 raci\xf3n",B.akz,B.am3,null,640,42,B.a1,B.cv,!1)
B.aHl=s(["200 g de fideos de fideu\xe1 (del n.\xba 0 o del 1)","600 ml de fumet de pescado (de brick o casero)","200 g de gambas peladas","150 g de sepia o calamar en trozos","1 tomate maduro rallado","2 dientes de ajo picados","1 cucharadita de piment\xf3n dulce","Unas hebras de azafr\xe1n o colorante (opcional)","3 cucharadas de aceite de oliva","Sal","Alioli y lim\xf3n para servir"],t.s)
B.aIa=s(["Calienta el fumet en un cazo y d\xe9jalo a fuego m\xednimo. Tiene que estar muy caliente cuando lo eches.","En una paellera o sart\xe9n grande, calienta el aceite y dora la sepia 3-4 minutos. A\xf1ade las gambas, salt\xe9alas 1 minuto, s\xe1calas y res\xe9rvalas (la sepia se queda).","Echa el ajo y, antes de que se dore, el tomate rallado. Sofr\xede 5 minutos a fuego medio hasta que pierda el agua.","A\xf1ade los fideos y tu\xe9stalos 2-3 minutos removiendo, hasta que cojan color dorado.","Pon el piment\xf3n, remueve 10 segundos (sin que se queme) y echa 500 ml de fumet caliente con el azafr\xe1n. Prueba de sal.","Cocina a fuego medio-fuerte 8-10 minutos sin remover. Si se queda seco antes de tiempo, a\xf1ade un poco del fumet que sobra.","Cuando falten 2 minutos, reparte las gambas por encima.","Apaga y deja reposar 3 minutos tapada con un pa\xf1o. Si te gustan los fideos de punta, m\xe9tela 3-4 minutos al grill del horno.","Sirve con alioli y un chorro de lim\xf3n."],t.s)
B.aWg=new A.aS("fideua","Fideu\xe1 de pescado y marisco",35,"2 raciones",B.aHl,B.aIa,"La proporci\xf3n es de 2,5 veces de fumet por el peso de fideos. Para ganar peso, acomp\xe1\xf1ala de pan y una cucharada de alioli (+100 kcal).",710,45,B.a1,B.cv,!1)
B.ana=s(["250 g de lentejas pardinas","1 chorizo (unos 100 g) en rodajas","1 cebolla","1 zanahoria","1 pimiento verde","2 dientes de ajo","1 patata mediana","1 cucharadita de piment\xf3n dulce","1 hoja de laurel","2 cucharadas de aceite de oliva","Sal"],t.s)
B.awb=s(["Lava las lentejas en un colador (las pardinas no necesitan remojo).","Pica la cebolla, el pimiento, el ajo y la zanahoria en trozos peque\xf1os.","En una olla con el aceite, sofr\xede las verduras 8 minutos a fuego medio.","A\xf1ade el chorizo y deja 2 minutos para que suelte su grasa.","Echa el piment\xf3n, remueve r\xe1pido y a\xf1ade las lentejas, el laurel y agua hasta cubrirlas dos dedos.","Cuando hierva, baja el fuego, a\xf1ade la patata en trozos (cascados, no cortados del todo) y cuece 30-35 minutos.","Prueba de sal al final y deja reposar 5 minutos."],t.s)
B.aWF=new A.aS("lentejas","Lentejas con chorizo y verduras",45,"3 raciones",B.ana,B.awb,"Al d\xeda siguiente est\xe1n a\xfan mejor. Cong\xe9lalas en t\xe1pers de una raci\xf3n.",620,31,B.a1,B.eT,!1)
B.aIq=s(["1 bote de garbanzos cocidos (400 g)","200 g de espinacas frescas o congeladas","2 huevos","2 dientes de ajo","1 rebanada de pan","1 cucharadita de comino (opcional)","1 cucharadita de piment\xf3n","3 cucharadas de aceite de oliva","Sal"],t.s)
B.aw3=s(["Cuece los huevos 10 minutos, enfr\xedalos y p\xe9lalos.","Lava los garbanzos del bote con agua y esc\xfarrelos.","En una sart\xe9n con el aceite, fr\xede los ajos laminados y la rebanada de pan hasta que est\xe9n dorados. S\xe1calos y m\xe1jalos con un tenedor.","En ese aceite, saltea las espinacas hasta que se reduzcan.","A\xf1ade los garbanzos, el majado, el comino, el piment\xf3n y un vaso peque\xf1o de agua. Cocina 5 minutos.","Sirve con los huevos en cuartos por encima."],t.s)
B.aWD=new A.aS("garbanzos-espinacas","Garbanzos con espinacas y huevo",20,"2 raciones",B.aIq,B.aw3,null,520,24,B.a1,B.eT,!1)
B.aof=s(["350 g de pechuga o contramuslo de pollo","160 g de arroz (en crudo)","1 cebolla","1 lata de leche de coco (o 200 ml de nata para cocinar)","1 cucharada de curry en polvo","2 cucharadas de tomate frito","1 cucharada de aceite","Sal"],t.s)
B.ap6=s(["Pon a cocer el arroz en agua con sal (15-18 minutos) y esc\xfarrelo.","Corta el pollo en dados y la cebolla en trozos peque\xf1os.","Dora el pollo en una sart\xe9n con el aceite, 5 minutos. S\xe1calo.","En la misma sart\xe9n pocha la cebolla 5 minutos, a\xf1ade el curry y remueve 30 segundos.","A\xf1ade la leche de coco y el tomate frito, vuelve a meter el pollo y cocina 8-10 minutos a fuego suave.","Sirve el pollo con su salsa sobre el arroz."],t.s)
B.aWm=new A.aS("pollo-curry","Pollo al curry con arroz",30,"2 raciones",B.aof,B.ap6,"Con leche de coco tiene m\xe1s calor\xedas que con nata ligera: perfecto para ganar peso.",930,51,B.a1,B.dl,!1)
B.ais=s(["500 g de carne picada (mixta o de ternera)","1 huevo","2 cucharadas de pan rallado","1 diente de ajo picado y perejil","Harina para rebozar","1 cebolla","400 g de tomate triturado","1 vaso peque\xf1o de caldo o agua","Aceite de oliva y sal"],t.s)
B.alC=s(["Mezcla la carne con el huevo, el pan rallado, el ajo, el perejil y sal.","Haz bolas del tama\xf1o de una nuez y p\xe1salas por harina.","Fr\xedelas en una sart\xe9n con un dedo de aceite hasta que est\xe9n doradas. S\xe1calas.","Quita casi todo el aceite y pocha la cebolla picada 5 minutos.","A\xf1ade el tomate y el caldo, cocina 10 minutos y mete las alb\xf3ndigas.","Cocina todo junto 10-15 minutos a fuego suave. Sirve con arroz, patatas o pan."],t.s)
B.aWd=new A.aS("albondigas","Alb\xf3ndigas en salsa de tomate",40,"3 raciones",B.ais,B.alC,null,550,36,B.a1,B.dl,!1)
B.ax2=s(["90 g de arroz (en crudo)","2 huevos","1 pl\xe1tano","4 cucharadas de tomate frito","Aceite de oliva","Sal"],t.s)
B.aJ5=s(["Cuece el arroz en agua con sal 15-18 minutos y esc\xfarrelo.","Calienta el tomate frito.","Corta el pl\xe1tano a lo largo y d\xf3ralo en una sart\xe9n con unas gotas de aceite.","Fr\xede los huevos.","Monta el plato: arroz, tomate por encima, los huevos y el pl\xe1tano al lado."],t.s)
B.aX2=new A.aS("arroz-cubana","Arroz a la cubana",25,"1 raci\xf3n",B.ax2,B.aJ5,null,760,24,B.a1,B.cv,!1)
B.ajp=s(["200 g de espaguetis","250 g de carne picada de ternera","1 cebolla","1 zanahoria","400 g de tomate triturado","1 cucharadita de or\xe9gano","Queso rallado","Aceite de oliva y sal"],t.s)
B.ajV=s(["Pica la cebolla y ralla la zanahoria. Sofr\xedelas 6 minutos con aceite.","A\xf1ade la carne, sube el fuego y deshazla con la cuchara hasta que no quede rosa.","Echa el tomate, el or\xe9gano y sal. Cocina 15 minutos a fuego suave.","Mientras, cuece los espaguetis en agua con sal el tiempo del paquete.","Mezcla la pasta con la salsa y sirve con queso rallado."],t.s)
B.aWY=new A.aS("espaguetis-bolonesa","Espaguetis a la bolo\xf1esa",30,"2 raciones",B.ajp,B.ajV,"Haz el doble de salsa y cong\xe9lala: tienes otra comida en 10 minutos.",850,41,B.a1,B.cv,!1)
B.avr=s(["4 muslos o contramuslos de pollo","3 patatas medianas","1 cebolla","1 lim\xf3n","3 dientes de ajo","Romero o tomillo","3 cucharadas de aceite de oliva","Sal y pimienta"],t.s)
B.azE=s(["Precalienta el horno a 200 \xb0C.","Corta las patatas en rodajas finas y la cebolla en tiras. Ponlas en la bandeja con sal y la mitad del aceite.","Coloca el pollo encima con la piel hacia arriba, los ajos chafados, el lim\xf3n en rodajas, las hierbas, sal, pimienta y el resto del aceite.","Hornea 45-50 minutos, hasta que la piel est\xe9 dorada y las patatas tiernas."],t.s)
B.aXu=new A.aS("muslos-horno","Muslos de pollo al horno con patatas",55,"2 raciones",B.avr,B.azE,"Mientras se hace no tienes que hacer nada: ideal para los d\xedas de entreno.",890,47,B.a1,B.dl,!1)
B.alu=s(["1 calabac\xedn","1 pimiento rojo y 1 verde","1 cebolla","400 g de tomate triturado","2 huevos","Pan para acompa\xf1ar","Aceite de oliva, sal y una pizca de az\xfacar"],t.s)
B.aj0=s(["Corta todas las verduras en dados peque\xf1os.","Pocha la cebolla y los pimientos con aceite 10 minutos.","A\xf1ade el calabac\xedn y cocina 5 minutos m\xe1s.","Echa el tomate, sal y la pizca de az\xfacar. Cocina 15 minutos a fuego suave.","Fr\xede los huevos y s\xedrvelos encima del pisto, con pan."],t.s)
B.aWK=new A.aS("pisto-huevo","Pisto con huevo frito",35,"2 raciones",B.alu,B.aj0,null,300,13,B.a1,B.eo,!1)
